Method.Implementation:
	Set usrNm = "lpjnaras"
	set svnOper = 0

	if ( (fileNm = "") || (comment = "") )
	{
		Quit $$$ERROR(6484, "FileName")
	}
	if ( ' ##class(%File).Exists(fileNm) )
    {
	    Set svnOper = 1 ; Don't do svn add
    }  
    // Get latest from Ensemble DB 
	&sql(SELECT  InternalName INTO :InternalName FROM ITFCOMMON.SrcCtrlInfo WHERE FileName=:fileNm)
	IF SQLCODE = 0 
    { 
	       Set sc=$$Export^%occXMLExport(fileNm,"-d /diffexport",InternalName)
    }
    if ( (svnOper) && (##class(%File).Exists(fileNm)) )
    {
	   Set cmd = "svn --username " _usrNm _ " -- password " _ passwd _ " add -N " _ fileNm  ; a non-recursive commit (-N)

	   Set stat = $ZF(-1, cmd)
	   if stat '= 0
	   {
	      set svnOper = 1
	      Quit $$$ERROR(5880, "SVN add error")
	   }
    }
    else
    {
	    set svnOper = 1
    }
	if ((svnOper) && (##class(%File).Exists(fileNm)) )
    {
	    Set cmd = "svn --username " _usrNm _ " -- password " _ passwd _ "  commit -N -m """ _ comment _ """ " _ fileNm  ; a non-recursive commit (-N)

		Set stat = $ZF(-1, cmd)
		if stat '= 0
		{
		  Quit $$$ERROR(5880, "SVN commit error")
		}
		 Do ..AddToSourceControl(InternalName)
    }
 Quit $$$OK

	Set usrNm = $username
	set files = ""
	set SelectedIntfiles = ""

	if ( (Selectedfiles = "") || (comment = "") )
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)

		if ( fileNm '= "")
		{
		   SET files = files _ " " _ fileNm 
	    }
	    else
	    {
		    continue
	    }
	    Do ..AddDirectoriesToSvn(fileNm, passwd)

        // Get latest from Ensemble DB 

	    &sql(SELECT  InternalName INTO :InternalName FROM ITFCOMMON.SrcCtrlInfo WHERE FileName=:fileNm)

	    IF SQLCODE = 0 
        { 
	        Set sc=$$Export^%occXMLExport(fileNm,"-d /diffexport",InternalName)
	        if $$$ISOK(sc)
	        {
	          set SelectedIntfiles = SelectedIntfiles _ "," _ InternalName
         	  // Do ##class(ITFCOMMON.Utility).WriteToFile($NAMESPACE _ " " _ fileNm _" -d /diffexport " _InternalName)
	          Do ..AddToSvn(fileNm, 0, passwd)	
	        }
        }
	}

	if (files '= "" )
    {

	    Set cmd = "svn --username " _ usrNm _ " --password " _ passwd  _ " commit -N -m """ _ comment _ """ " _ files  ; a non-recursive commit (-N)

		Set stat = $ZF(-1, cmd)
		if stat '= 0
		{
			// Do ##class(ITFCOMMON.Utility).WriteToFile("SVN commit error: " _ cmd)
		  Quit $$$ERROR(5880, "SVN commit error")
		}

    }
    For I=1:1:$L(SelectedIntfiles,",")
	{
		Set InternalName = $P(SelectedIntfiles,",",I)

		if ( InternalName '= "")
		{
          Do ..AddToSourceControl(InternalName)
		}
	}
     Quit $$$OK

Set usrNm = $username
set stat = $$$ERROR(9100, "Could not add")
SET fullPath =  $$$SVNBASEDIR 
set svnPath=$REPLACE(fName, fullPath _ "/", "")

SET fileParts = $Length(svnPath, "/")

FOR ind=1:1:fileParts - 1
{
	set dirName = $PIECE(svnPath, "/", ind)
	set fullPath = fullPath _ "/" _ dirName
	if ( ' ##class(%Library.File).Exists(fullPath))
	{
		Do ##class(%File).CreateDirectory(fullPath)
	}
	Do ..AddToSvn(fullPath, 1, passwd)
}

Set usrNm = $username
Set cmd = "svn --username " _ usrNm _ " --password " _ passwd _ " info " _ fullPath
Set stat = $ZF(-1, cmd)
// Do ##class(ITFCOMMON.Utility).WriteToFile( cmd )
If stat '= 0 	
{
	Do ##class(ITFCOMMON.Utility).WriteToFile( cmd )
	Set cmd = "svn --username " _ usrNm _ " --password " _ passwd _ " add -N " _ fullPath  ; a non-recursive commit (-N)   
	Set stat = $ZF(-1, cmd)
	if (commit)
	{		
	  Set cmd = "svn --username " _ usrNm _ " --password " _ passwd _ " commit -m ""testing"" -N " _ fullPath  ; a non-recursive commit 
	  Set stat = $ZF(-1, cmd)
	}
}
Quit stat


	set tStatus = $$$ERROR(100, "Error in checkout")

	set username = $username

	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		if ( fileNm '= "")
		{	 
			If ##class(%File).Exists(fileNm)
			{
	  			Do ##class(%File).Delete(fileNm)
			}			
			Set cmd= "svn --username " _ username _ " --password " _ passwd _ " update  " _ fileNm 

			Set status = $ZF(-1, cmd)

	  		if status = 0
	  		{
         		#; Call the function to do the load
         		Set tStatus=$system.OBJ.Load(fileNm,"-l-d")        
	  		}
		}
	}
	Quit tStatus


	set fileInfo = ""

	set username = $username

	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		if ( fileNm '= "")
		{	 
			set tempFile = 	fileNm _ "Temp" 		
			Set cmd= "svn --username " _ username _ " --password " _ passwd _ " info  " _ fileNm _ " >> " _ tempFile

			Set status = $ZF(-1, cmd)

	        Set cmd= "svn --username " _ username _ " --password " _ passwd _ " log  " _ fileNm _ " >> " _ fileNm _ tempFile 

			Set status = $ZF(-1, cmd)
	  		if status '= 0
	  		{
         		#; Call the function to do the load
         		Set tStatus=..GetFileContent(tempFile) 
         		Set fileInfo = fileInfo _ tStatus       
	  		}
	  		else
	  		{
		  		SET fileInfo = "svn command failed"
	  		}
		}
	}
	Quit fileInfo


	Do ..CheckSvnSetup(passwd)
  	Set SrcCtrlList=$LB("Ens.BusinessProcessBPL", "Ens.Rule.Definition", "Ens.DataTransformDTL", 
   		"Ens.Rule.FunctionSet", "%Persistent", "%Studio.SourceControl.Base")
   	set acProd = ##class(Ens.Director).GetActiveProductionName()
   	if (acProd = "")
   	{
	  	Set acProd = $NAMESPACE
   	}
	// Do ##class(ITFCOMMON.Utility).WriteToFile("GetItems: "_ " " _ acProd) 


    Set rset = ##class(%ResultSet).%New("%Dictionary.ClassDefinition:Summary")

    Do rset.Execute()


    While (rset.Next(.sc)) // next row of result set
    {
    	If ($SYSTEM.Status.IsOK(sc)) // check for errors
    	{
	    	set clNm =  rset.Data("Name")
          	set findInd = $FIND(clNm, acProd)
            set findInd2 = $FIND(clNm, $NAMESPACE)

            if ( ((findInd > 0) || (findInd2 > 0)) && ($LF(SrcCtrlList, rset.Data("Super")) ) )
           	{
	             // Do ##class(ITFCOMMON.Utility).WriteToFile(clNm)	
	             Do ..AddToSourceControl(clNm _ ".CLS")
           	}
        }
   	}


	Quit $$$OK

	 //  Do ##class(ITFCOMMON.Utility).WriteToFile("CheckSvnSetup" _ $$$SVNBASEDIR)
	 // check for the parent directory
	 SET usrBaseDir = $$$USRBASEDIR _ $username
	 IF ' ##class(%File).DirectoryExists(usrBaseDir)
	 {
		 Quit $$$ERROR(100, "User Home directory does not exists")
     }

     SET svnBaseDir = usrBaseDir _ $$$SVNBASEDIR

	 IF ' ##class(%File).DirectoryExists(svnBaseDir)
     {
         Do ##class(%File).CreateDirectory(svnBaseDir)
	  }

     // Checkout complete tree
     SET svntrunk = svnBaseDir _ $$$SVNTRUNK
     // Do ##class(ITFCOMMON.Utility).WriteToFile(svntrunk)
     IF ' ##class(%File).DirectoryExists(svntrunk)
	 {
	   set svnCmd = $$$SVNCHECKOUT _ " --username " _ $username _ " --password " _ passwd _ " " _ $$$SVNURL _ " " _ svnBaseDir 
	   Set status = $ZF(-1, svnCmd)
	   // Do ##class(ITFCOMMON.Utility).WriteToFile(svnCmd _ " " _ status)
	 }
     Quit $$$OK

	set fileStamp = ""

	if (##class(%File).Exists(fileNm) )
	{
		set fTime = ##class(%File).GetFileDateModified(fileNm)
		set fileStamp = $ZDATETIME(fTime, 3, 1)

		// Get SVN output to a TEMP file
		set TempFile =  fileNm _ "tempFileSvn"
		set cmd = $$$SVNINFO _ fileNm _ " > " _ TempFile
		Set status = $ZF(-1, cmd)

		if (##class(%File).Exists(TempFile) )
		{
         Set fileObj=##class(%Library.File).%New(TempFile)
         Do fileObj.Open("RS") ; Read mode and as stream
         While 'fileObj.AtEnd 
         {
	        set reLn = fileObj.ReadLine(,.sc,.eol)
	        set dtTmInd = $F(reLn, $$$SVNCHECKINTIME)

	        if dtTmInd > 0
	        {
		        // find last time and strip spaces, Get date and time 
		        set tmPart = $ZSTRIP($Extract(reLn, dtTmInd, $Length(reLn)),"<>W")
	            set fileStamp = $Piece(tmPart, " ", 1) _ " " _ $Piece(tmPart, " ", 2)
	        }
         }
         Do fileObj.Close()
         Do ##class(%Library.File).Delete(TempFile)
       }

	}
	Quit fileStamp


	set initCom=""
	set dbFile = ""
	Set file=..ExternalName(InternalName)
	set intTime= ##class(%RoutineMgr).TS(InternalName)

	set fileStamp = ..GetSvnTime(file)
	// Do ##class(ITFCOMMON.Utility).WriteToFile("AddToSourceControl: " _ file)

	if ( file '= "" )
	{
		&sql(SELECT  FileName INTO :dbFile FROM ITFCOMMON.SrcCtrlInfo WHERE FileName=:file)
		if SQLCODE '= 0 {
	       &sql(INSERT INTO ITFCOMMON.SrcCtrlInfo SET InternalName = :InternalName ,FileName=:file,ClassModifiedTime=:intTime,FileModifiedTime=:fileStamp)
           IF SQLCODE '= 0 {
               WRITE !,"Insert failed " _ file _ " CODE: " _ SQLCODE _ " IntNm: " _ InternalName _ " intTime " _ intTime _ " :fileStamp" _ fileStamp
           }
        }
        else
        {
	        // Write !, "file exists: " _ dbFile
	        &sql(UPDATE ITFCOMMON.SrcCtrlInfo SET ClassModifiedTime=:intTime,FileModifiedTime=:fileStamp WHERE FileName=:file )
            // WRITE !,"Update " _ file _ " CODE: " _ SQLCODE 
        }
	}
	Quit $$$OK

// Write !, "Mapping Name"
If $data(^|"ITFCOMMON"|ItfSourceCtrl)'=11 
{
	Set src = ..setSources()
	// Write !,"^|""ITFCOMMON""|ItfSourceCtrl is not setup so hooks will not work"
	Set src = $data(^|"ITFCOMMON"|ItfSourceCtrl) 
	Write !, "Sources set: " _ src
}	
If $data(^|"ITFCOMMON"|ItfSourceCtrl)'=11 Write !,"^|""ITFCOMMON""|ItfSourceCtrl is not setup so hooks will not work" Quit ""

// For an abstract document, use the GetOther() method to try to determine its "real" class
If ##class(%RoutineMgr).UserType(InternalName,.docclass,.doctype) {
	// Check for a real abstract document subclass (or GetOther() may not work)
	If $classmethod(docclass,"%IsA","%Studio.AbstractDocument") {
		// Grab the actual name
		Set actualName = $classmethod(docclass,"GetOther",InternalName)
		// The actualName is only valid if we get a single .cls as a result
		If actualName'[",",$ZCVT($P(actualName,".",$L(actualName,".")),"U")="CLS" {
			// We use what GetOther() gives us, thus Demo.Loan.FindRateProcess.bpl becomes Demo.Loan.FindRateProcess.cls
			Set InternalName = actualName
		}
	}
}	

If $$CheckProtect^%qccServer(InternalName) Quit ""
Set nam=$p(InternalName,".",1,$l(InternalName,".")-1),ext=$p(InternalName,".",$l(InternalName,".")),ext=$zcvt(ext,"u")
If nam="" Quit ""
If ext="PRJ",nam["Default_" Quit ""
If ext="CLS",$$$defClassKeyGet(nam,$$$cCLASSgeneratedby)'="" Quit ""
Set default=0
Set p=$order(^|"ITFCOMMON"|ItfSourceCtrl(ext,nam)) For  s p=$order(^|"ITFCOMMON"|ItfSourceCtrl(ext,p),-1) Quit:p=""  If $extract(nam,1,$length(p))=p,$data(^|"ITFCOMMON"|ItfSourceCtrl(ext,p),found) Quit
If $data(found)=0,$data(^|"ITFCOMMON"|ItfSourceCtrl(ext,"*"),found) Set default=1
If $data(found)=0 Quit ""
If InternalName["/" {
	Set InternalName=$extract(InternalName,$length(p)+1,*)
	Quit $translate(found_$translate(InternalName,"%","_"),"\","/")
}
If ext="CLS"||(ext="PRJ")||(##class(%RoutineMgr).UserType(InternalName)) Quit $translate(found_$translate(nam,".%","/")_".xml","\","/")
Quit $translate($g(found)_$tr(nam,"%"_$s(default:".",1:""),"_/")_".xml","\","/")
